# Rule hypothesis: decompose shape into 2x2 windows; full window->1; tromino window-> color by missing corner (TL=2,TR=4,BL=3,BR=1?); verify all demos with a cover algorithm.
def solve(Ig, verbose=False):
    I=np.array(Ig); H,W=I.shape
    m=(I==8)
    out=np.full((H,W),-1)
    rem=np.zeros((H,W),bool); rem[m]=True
    # greedy: process all tromino windows first (stronger signal), then full squares, single cells
    def win_color(r,c):
        pts=[(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
        pres={p for p in pts if rem[p]}
        miss={(a,b) for a,b in pts if (a,b) not in pres}
        if len(pres)==3:
            dr,dc=min(pres[0]); 
            mm=list(miss)[0]; d,d2=mm
            # TL(0,0)->2 TR(0,1)->4 BL(1,0)->3 BR(1,1)->1
            v={'0,0':2,'0,1':4,'1,0':3}.get(f"{d},{d2}")
            return v if v is not None else -1
        if len(pres)==4: return 1
        if len(pres)==1: return 1
        return -2
    assigned=set()
    order=[]
    for r in range(H-1):
        for c in range(W-1):
            pts=[(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
            pres=sum(1 for p in pts if rem[p])
            if pres>=3: order.append((pres,r,c))
    for pres,r,c in sorted(order):
        if pres<3: continue
        col=win_color(r,c)
        if col==-1 or any(out[x,y]!=-1 for x,y in [(r,c),(r,c+1),(r+1,c),(r+1,c)]): continue
        for x,y in [(r,c),(r,c+1),(r+1,c),(r+1,c+1)]:
            if m[x,y]: out[x,y]=col; rem[x,y]=False
    # leftover cells: singletons -> 1
    for x in range(H):
        for y in range(W):
            if m[x,y] and rem[x,y]: out[x,y]=1
    return out.tolist()
