# Rule: tromino 2x2 window -> color by missing corner: TL->2, TR->4, BL->3; full square -> 1. Verify demos with proper greedy cover.
def solve(Ig):
    I=np.array(Ig); H,W=I.shape
    m=(I==8)
    out=np.full((H,W),-1); rem=m.copy()
    def win_color(r,c):
        pts=[(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
        pres=[p for p in pts if rem[p]]
        if len(pres)==3:
            miss=[p for p in pts if p not in rem]
            dr,dc=miss[0]
            v={'0,0':2,'0,1':4,'1,0':3}.get(f"{dr},{dc}")
            return v if v is not None else -1
        if len(pres)==4: return 1
        return -2
    order=[]
    for r in range(H-1):
        for c in range(W-1):
            pts=[(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
            n=sum(1 for p in pts if rem[p])
            if n>=3: order.append((n,r,c))
    for n,r,c in sorted(order,key=lambda x:-x[0]):
        col=win_color(r,c)
        if col==-1 or any(out[x,y]!=-1 for x,y in [(r,c),(r,c+1),(r+1,c),(r+1,c)]): continue
        for x,y in [(r,c),(r,c+1),(r+1,c),(r+1,c+1)]:
            if m[x,y]: out[x,y]=col; rem[x,y]=False
    for x in range(H):
        for y in range(W):
            if m[x,y] and rem[x,y]: out[x,y]=1
    return [[int(v) if v>=0 else 0 for v in row] for row in out]
